//! A worked mental model, counterexample and experiment for every circuit
//! level. Kept separate from hints so learning does not require revealing
//! the wiring solution. Tests prevent newly added levels being left bare.
use makine_lang::tr;

pub struct Guide {
    pub concept: &'static str,
    pub example: &'static str,
    pub trap: &'static str,
    pub experiment: &'static str,
}

pub fn guide(chip: &str) -> Option<Guide> {
    macro_rules! g {
        ($ct:expr,$ce:expr,$et:expr,$ee:expr,$tt:expr,$te:expr,$xt:expr,$xe:expr) => {
            Guide {
                concept: tr!($ct, $ce),
                example: tr!($et, $ee),
                trap: tr!($tt, $te),
                experiment: tr!($xt, $xe),
            }
        };
    }
    Some(match chip {
        "Not"=>g!("Bir tel yalnızca sinyali taşır; NOT onu tersler. NAND, iki giriş birden 1 olmadıkça 1 üretir. Aynı sinyali iki girişe vermek yeni bir zaman adımı eklemez.","A wire carries a signal; NOT inverts it. NAND outputs 1 unless both inputs are 1. Feeding the same signal into both pins adds no new time step.","in=0 → out=1; in=1 → out=0.","in=0 → out=1; in=1 → out=0.","NAND'ın bir girişini boş bırakmak NOT yapmaz; boş giriş burada 0 okunur.","Leaving one NAND input open does not make NOT; an unconnected input reads 0 here.","İki NOT'u art arda dene: başlangıç sinyali geri geliyor mu?","Try two NOTs in series: does the original signal return?"),
        "And"=>g!("AND birlikte gereken iki şartı temsil eder. NAND'ın sonucu bunun tersidir. Önceki NOT seviyen artık kullanılabilir bir parçadır; içindeki NAND'lar kaybolmaz.","AND represents two conditions required together. NAND produces its opposite. Your earlier NOT is now a reusable part; its internal NANDs still exist.","a=1,b=0 → 0; a=1,b=1 → 1.","a=1,b=0 → 0; a=1,b=1 → 1.","Yalnızca 1,1 satırına bakmak yetmez; dört giriş birleşimini de dene.","Checking only 1,1 is insufficient; test all four input combinations.","Bir giriş hep 1 olursa AND'ın diğer girişe etkisi ne?","What does AND do to the other input if one input stays 1?"),
        "Or"=>g!("OR en az bir şartın sağlanmasıdır; yalnızca ikisi de 0 iken 0 olur. De Morgan, girişleri tersleyerek aynı davranışın NAND ile kurulabileceğini gösterir.","OR means at least one condition holds; only two zero inputs produce zero. De Morgan shows how inverted inputs and NAND implement the same behaviour.","0 OR 1=1; 1 OR 1=1. OR, XOR değildir.","0 OR 1=1; 1 OR 1=1. OR is not XOR.","İki giriş 1 iken 0 üretiyorsan özel veya yapmışsındır.","If two ones produce zero, you have built exclusive OR.","Bir giriş hep 0 olursa diğer giriş değişmeden geçiyor mu?","Does the other input pass unchanged if one input stays 0?"),
        "Xor"=>g!("XOR girişler farklıyken 1 olur. İki biti toplamanın alt basamağıdır; eldeyi bu çıkış tek başına taşımaz. Ortak ara sonuçları paylaşarak NAND sayısını azaltabilirsin.","XOR outputs 1 when inputs differ. It is the low bit of adding two bits; it does not carry the overflow by itself. Share intermediate results to reduce NAND count.","1 XOR 1=0; fakat 1+1 ikilik 10'dur: elde ayrı çıkış gerektirir.","1 XOR 1=0, but 1+1 is binary 10: carry requires a separate output.","XOR'u sadece OR sanmak 1,1 testini bozar.","Treating XOR as OR fails the 1,1 test.","a XOR 0 ve a XOR 1'i karşılaştır: bir XOR nasıl kontrollü NOT olur?","Compare a XOR 0 with a XOR 1: how can XOR become a controlled NOT?"),
        "Mux"=>g!("MUX veri üretmez; hangi verinin geçeceğini seçer. sel bir verinin biti değil, seçim kontrolüdür. İki yolun yalnızca biri etkin olmalı, sonra yollar birleşir.","A MUX does not invent data; it chooses which data passes. sel controls selection rather than being part of the data. Enable one of two paths and combine them.","a=1,b=0: sel=0 → out=1; sel=1 → out=0.","a=1,b=0: sel=0 → out=1; sel=1 → out=0.","a ve b aynıyken yanlış bağlanmış sel görünmeyebilir; farklı veriyle dene.","Equal a and b can hide a reversed selector; test with different values.","a ve b'yi değiştirip sel'i terslersen aynı sonuç korunuyor mu?","Swap a and b and invert sel: is the result preserved?"),
        "Demux"=>g!("DEMUX tek veriyi seçilen yola yönlendirir. Seçilmeyen yol 0 olmalıdır. Daha sonra RAM yazma iznini yalnızca bir kayda dağıtırken bu fikri kullanacaksın.","DEMUX routes one value to a selected path. The unselected output must be zero. Later you use this to route write enable to exactly one RAM register.","in=1,sel=0 → a=1,b=0; sel=1 → a=0,b=1.","in=1,sel=0 → a=1,b=0; sel=1 → a=0,b=1.","İki çıkışa da giriş vermek seçim yapmaz; RAM'de iki kayıt birden yazılır.","Driving both outputs with the input makes no selection; it would write two RAM registers.","in=0 iken sel değişirse çıkışlar neden hâlâ 0?","Why do both outputs stay zero when sel changes with in=0?"),
        "Mux32"|"Mux4"=>g!("Bus bir sayı sihri değil, yan yana bitlerdir. Her bit için aynı MUX davranışını uygula; bütün kopyalar aynı sel'i paylaşır. Tekrar ayarı bitleri paralel çalıştırır, zamanda tekrar etmez.","A bus is parallel bits, not numeric magic. Apply the same MUX to each bit and share sel. Repeat creates parallel copies, not repeated time steps.","a=5 (0101), b=9 (1001), sel=1 → 9.","a=5 (0101), b=9 (1001), sel=1 → 9.","sel'i 4/32 ayrı bağımsız değer sanma; tek seçim bütün kelimeyi seçer.","sel is not 4/32 independent choices; one selection chooses the entire word.","a ve b'nin yalnızca en üst biti farklıyken de sınama yap.","Test values differing only at the highest bit."),
        "HalfAdder"=>g!("İki bir-bit sayının toplamı iki bit sürebilir. sum düşük bit, carry sonraki basamağa giden bittir. Aynı a,b girişleri iki farklı mantık fonksiyonuna gider.","Two one-bit numbers may need two result bits. sum is the low bit; carry goes to the next column. The same inputs feed two different logic functions.","1+1=10 → sum=0, carry=1. 1+0=01 → sum=1,carry=0.","1+1=10 → sum=0,carry=1. 1+0=01 → sum=1,carry=0.","carry ile sum yer değişirse 1+0 ve 1+1 ikisi de yanlış olur.","Swapping sum and carry breaks both 1+0 and 1+1.","Dört satırı ikilik iki-bit sonuç olarak yan yana yaz.","Write all four rows as two-bit binary results."),
        "FullAdder"=>g!("Tam toplayıcı üç biti toplar: a,b ve önceki basamaktan c. Önce iki biti, sonra ara toplamla c'yi toplayabilirsin. İki yarım toplamdan oluşan eldeler OR ile birleşir.","A full adder adds a,b and incoming carry c. Add two bits first, then add c to that sum. OR the two half-addition carries.","1+1+1=11 → sum=1,carry=1.","1+1+1=11 → sum=1,carry=1.","c'yi yok sayan devre bazı satırlarda doğru görünür; özellikle c=1'i dene.","Ignoring c passes some rows; explicitly test c=1.","a=b=0 iken c'yi değiştir ve iki çıkışı izle.","Toggle c with a=b=0 and observe both outputs."),
        "Adder8"|"Adder32"|"Adder4"=>g!("Basamak basamak toplamada elde düşük bitten yüksek bite gider. Her basamak a[i],b[i] ve gelen eldeyi toplar. Son elde sayının sınırını aşan bittir; toplamın parçası değildir.","Ripple addition sends carry from low bits to high bits. Each column adds a[i],b[i] and incoming carry. The last carry is the overflow bit, separate from sum.","Dört bit örneği: 1111+0001+0=1 0000. sum=0,carry=1.","Four-bit example: 1111+0001+0=1 0000. sum=0,carry=1.","Tekrar ayarı tam toplayıcıların eldelerini birbirine zincirlemez; bu bağlantı ayrı kurulmalı.","Repeat does not chain full-adder carries; wire that chain explicitly.","Bütün bitleri 1 olan sayıya 1 ekle; sonra c girişini de 1 yap.","Add 1 to an all-ones number; then set input c to 1 too."),
        "Sub32"|"AddSub8"=>g!("Sabit genişlikte -b = NOT b + 1. Toplayıcıya a, terslenmiş b ve elde 1 vererek çıkarma yaparsın. AddSub8'de XOR, sub=1 olduğunda b'yi tersler; sub aynı zamanda elde girişidir.","At fixed width, -b=NOT b+1. Add a, inverted b and carry-in 1 to subtract. In AddSub8, XOR inverts b when sub=1; sub is also the carry-in.","8-bit örnek: 3-5=254 (11111110); işaretli yorumda -2.","8-bit example: 3-5=254 (11111110), which represents signed -2.","NOT b tek başına -b değildir; +1'i unutma.","NOT b alone is not -b; do not omit +1.","a=b için sonucu ve a=0,b=1 için bit desenini incele.","Inspect a=b, then the bit pattern for a=0,b=1."),
        "Latch"=>g!("Hafıza için çıkışın eski değeri geleceği etkilemelidir: geri besleme. set/reset etkin değilken çapraz kapılar önceki durumu korur. Bu devre saatli değildir; geçerli giriş değişince tepki verir.","Memory needs feedback: the old output affects the future. Cross-coupled gates retain state while set/reset are inactive. This circuit has no clock; valid input changes affect it immediately.","set=1,reset=0 → q=1; sonra ikisini 0 yap → q hâlâ 1.","set=1,reset=0 → q=1; then both 0 → q stays 1.","set=reset=1 durumu sözleşmede tanımsız olabilir; bunu sıradan veri satırı sanma.","set=reset=1 may be undefined by the contract; do not treat it as an ordinary data case.","Kısa set darbesi verip bırak, ardından reset darbesi ver.","Apply a short set pulse, release it, then pulse reset."),
        "DLatch"=>g!("D mandal açıkken d'yi izler, kapalıyken son değerini tutar. en seviye duyarlıdır: yükselen kenar beklemez. SR'nin set ve reset girişlerini aynı anda etkin yapmadan d'yi seçmelisin.","A D latch follows d while enabled and holds the last value when disabled. en is level-sensitive, not edge-triggered. Select set/reset from d without asserting both together.","en=1,d=1 → q=1; en=0,d=0 → q=1 kalır.","en=1,d=1 → q=1; en=0,d=0 → q stays 1.","en=1 boyunca d değişiyorsa q'nun da değişmesi hata değil, mandal davranışıdır.","q changing with d throughout en=1 is correct latch behaviour.","en yüksek kalırken d'yi iki kez değiştir; DFF ile farkı sonra karşılaştır.","Change d twice while en stays high; later compare with DFF."),
        "DFF"=>g!("Flip-flop d'yi yalnızca clk'nin 0→1 geçişinde alır. Ana-köle düzeninde iki mandal zıt saat seviyelerinde açıktır. Düşükken ana hazırlanır, yükselen kenarda köleye aktarılır.","A flip-flop captures d only when clk goes 0→1. In a master-slave arrangement, two latches open on opposite clock levels. The master prepares while low; the edge transfers to the slave.","clk=0,d=1 → q eski; clk=1 → q=1; clk yüksekken d=0 → q yine 1.","clk=0,d=1 → q unchanged; clk=1 → q=1; change d=0 while high → q still 1.","clk yüksek olduğu sürece d'yi geçiriyorsan flip-flop değil mandal yapmışsındır.","Following d throughout clk=1 makes a latch, not a flip-flop.","Aynı yüksek saat içinde d'yi değiştir; q'nun korunduğunu doğrula.","Change d during the same high clock level and verify q is retained."),
        "Bit"|"Register32"|"Register4"|"MiniAcc8"=>g!("Kayıt, yazma izni olan flip-flop'lardır. load=0 iken yeni veri değil eski q geri beslenir. Çok bitli kayıtta bütün bitler aynı load ve clk'yi paylaşır. Reset ucu varsa en yüksek öncelikle sıfırlar.","A register consists of write-enabled flip-flops. With load=0, feed old q back rather than new data. All bits share load and clk. If present, reset has highest priority.","q=1,load=0,d=0 ve saat kenarı → q=1; load=1 sonraki kenarda → q=0.","q=1,load=0,d=0 at an edge → q=1; load=1 at the next edge → q=0.","load'u saat sinyali yerine koymak farklı kenarlar üretir; seçim veride yapılmalı.","Using load as the clock creates different edges; perform selection in the data path.","load düşükken birkaç saat ver; sonra açıp bir kez yaz.","Clock several times with load low, then enable and write once."),
        "Counter32"|"Counter12"|"MiniPc4"=>g!("Program sayacı, sonraki komutun adresini saklayan kayıttır. Artırma, atlama, durma ve reset durumları bir öncelik sırasıyla seçilir. RISC-V komutu 4 bayt, mini/4004 komut adresi başka birimdir: seviyedeki artış miktarını izle.","A program counter stores the next instruction address. Increment, jump, hold and reset follow explicit priorities. RISC-V instructions span four bytes; Mini/4004 address units differ. Follow this level's increment amount.","Reset etkin ve yükleme/atlama da etkin → sonraki adres 0; reset en önceliklidir.","Reset and load/jump asserted together → next address 0; reset wins.","Şu anki PC ile hesaplanmış sonraki PC'yi karıştırma: kenardan önce çıkış eski değerdir.","Do not confuse current PC and computed next PC: before the edge the output is the old value.","En büyük adresten bir artırıp sarmayı ve aynı anda iki kontrolü dene.","Increment the largest address to test wraparound, then assert two controls together."),
        "Ram8"=>g!("RAM adresi verinin kendisi değildir; hangi kaydın okunup yazılacağını seçer. Okuma kombinasyonel, yazma saat kenarında ve yalnızca we etkinse gerçekleşir. DEMUX yazma iznini, MUX ağacı okuma verisini seçer.","A RAM address selects which register to access; it is not the data itself. Reads are combinational, writes happen at clock edges with we enabled. DEMUX selects write enable; a MUX tree selects read data.","addr=3,d=42,we=1 ve kenar → yalnızca hücre3=42. addr=4 okumak hücre3'ü değiştirmez.","addr=3,d=42,we=1 at an edge → only cell3=42. Reading addr=4 does not alter cell3.","we'yi tüm kayıtlara dağıtmak belleği tek hücreye dönüştürür.","Broadcasting we to every register turns the memory into one shared cell.","İki adrese farklı veri yazıp adres değiştirerek ikisini geri oku.","Write distinct values at two addresses and read both back."),
        "MiniDecode"=>g!("Komut sayısının bazı bitleri işlem, bazı bitleri argümandır. Bu aşama komutu yürütmez; yalnızca bit alanlarını ayırır.","Some instruction bits select the operation; others hold an operand. This stage extracts fields; it does not execute the instruction.","instr=0x47=01000111 → op=4,arg=7.","instr=0x47=01000111 → op=4,arg=7.","Böl grupları düşük bitten başlar: ilk çıkış op değil arg.","Split starts at the low bits: its first output is arg, not op.","0x0F ve 0xF0 ile çıkışların ters bağlanmadığını dene.","Test 0x0F and 0xF0 to detect reversed outputs."),
        "MiniZero8"|"Zero32"=>g!("Sıfır testi bir sayının hiçbir bitinin 1 olmamasıdır. OR ile herhangi bir bitin 1 olup olmadığını bul, sonra tersle. Dengeli ağaç kapı sayısını değiştirmeden derinliği azaltır.","A value is zero when no bit is 1. OR the bits to detect any 1, then invert. A balanced tree reduces depth without changing gate count.","00000000 → zero=1; 10000000 → zero=0.","00000000 → zero=1; 10000000 → zero=0.","Yalnızca düşük veya işaret bitine bakma; ortadaki tek bir 1 de sıfır testini bozmalıdır.","Do not inspect only the low or sign bit; a single middle 1 must also mean nonzero.","Tek bir 1'i düşük bitten yüksek bite kaydırarak her biti sınamaya çalış.","Shift a single 1 from low to high bits to exercise every input bit."),
        "MiniControl"=>g!("Kontrol tablosu opcode'u hangi kayıt yazılacak, hangi veri seçilecek, bellek yazılacak mı sorularına dönüştürür. Önce her opcode için eşitlik sinyali, sonra her çıkış için bunların OR'unu kur.","Control maps opcodes to write enables, data selection and memory writes. First detect each opcode; then OR the relevant detections for each output.","ADD → load=1,alu=1; ST → we=1 ve load=0; JZ → yalnızca zero=1 ise jump=1.","ADD → load=1,alu=1; ST → we=1 and load=0; JZ → jump=1 only when zero=1.","ST'nin acc'ye yazması veya HLT'nin RAM'e yazması yasak yan etkidir.","Writing acc on ST or RAM on HLT is an unwanted side effect.","Bütün tanımsız opcode'larda çıkışların sıfır kaldığını dene.","Try every undefined opcode and check all outputs remain zero."),
        "MiniCpu"=>g!("Bu çip ROM ve RAM'in dışarıdan bağlandığı bir CPU'dur. MiniDecode alanları ayırır, MiniControl yolları seçer, AddSub8 hesaplar, MiniAcc8/MiniPc4 durumu kenarda saklar. İşlem yapmayan yolun hesaplanması sorun değil; yanlış yere yazılması sorundur.","This CPU connects to external ROM and RAM. MiniDecode extracts fields, MiniControl selects paths, AddSub8 computes, MiniAcc8/MiniPc4 store state at edges. Unused paths may compute; unintended writes are the problem.","LDI 3; ST 0; ADD 0 → acc sırasıyla 3,3,6; RAM[0]=3.","LDI 3; ST 0; ADD 0 → acc becomes 3,3,6; RAM[0]=3.","JZ'de sıfır testini rdata'ya değil mevcut acc'ye uygula.","JZ tests the current accumulator, not rdata.","Aynı kodu reset sonrası tekrar çalıştır; eski acc ve PC'nin silindiğini dene.","Run again after reset and verify old acc/PC are cleared."),
        "Compare32"=>g!("Eşitlik, işaretli küçüklük ve işaretsiz küçüklük farklı sonuçlardır. a-b sıfırsa eşittir. İşaretler farklıysa işaretli karşılaştırmada negatif olan küçüktür; işaretsizde taşıma/ödünç ilişkisini kullan.","Equality, signed less-than and unsigned less-than are distinct. A zero difference means equal. With different signs, the negative operand is smaller for signed comparison; unsigned comparison uses carry/borrow.","a=0xFFFFFFFF,b=1 → eq=0,lt=1,ltu=0.","a=0xFFFFFFFF,b=1 → eq=0,lt=1,ltu=0.","Farkın işaret biti tek başına taşmalı işaretli çıkarmada doğru karşılaştırma vermez.","The difference sign alone is insufficient when signed subtraction overflows.","0x80000000 ve 0x7FFFFFFF'i iki sırayla karşılaştır.","Compare 0x80000000 and 0x7FFFFFFF in both orders."),
        "ShiftLeft32"|"ShiftRight32"=>g!("Varil kaydırıcı 1,2,4,8,16 bitlik beş seçim katından oluşur. Kaydırma miktarının her biti bir katı açar; miktar kadar sırayla kapı koymak gerekmez. Sağa aritmetik kaydırma soldan işaret bitini, mantıksal kaydırma 0'ı doldurur.","A barrel shifter has five selection layers for 1,2,4,8,16 positions. Each amount bit enables a layer; no long serial shift is needed. Arithmetic right shift fills with the sign bit, logical shift with zero.","Sağa 0x80000000 >> 1: mantıksal 0x40000000, aritmetik 0xC0000000.","Right shift 0x80000000 by 1: logical 0x40000000, arithmetic 0xC0000000.","Boş kalan bitleri eski veriyle doldurma. Sıfır kaydırmada çıkış girişin aynısı olmalı.","Do not fill vacated positions with stale data. A zero shift must pass the input unchanged.","0,1,16,31 miktarlarıyla tek bir 1'in yerini izle.","Track a single 1 for shift amounts 0,1,16,31."),
        "Alu"=>g!("ALU ayrı işlemleri paralel hesaplayıp op'a göre bir sonucu seçer. funct3 alt işlemi, ek bit toplama/çıkarma ve mantıksal/aritmetik kaydırma ayrımını verir. Karşılaştırma sonuçları üst bitleri 0 olan sayılara dönüşür.","An ALU computes candidate operations in parallel and selects by op. funct3 chooses the operation; an extra bit distinguishes add/sub and logical/arithmetic shift. Comparison results become numbers with zero upper bits.","a=7,b=3: add=10,sub=4,and=3,xor=4; aynı girişler, farklı op.","a=7,b=3: add=10,sub=4,and=3,xor=4; same inputs, different op.","Hesap devreleri doğru olsa bile sonuç MUX sırası yanlışsa bütün opcode'lar karışır.","Correct computing blocks still fail if result MUX ordering is wrong.","Girişleri sabit tutup bütün op değerlerini gez; beklenen tabloyla karşılaştır.","Hold operands fixed and enumerate op values against the table."),
        "RegFile"=>g!("Register dosyası iki bağımsız okumaya ve bir yazmaya sahiptir. rs1/rs2 adres, rd yazma adresidir. x0 her zaman 0 olmalı; oraya yazma isteği yok sayılır. Okuma için saat beklenmez, yazma kenarda olur.","A register file has two independent reads and one write. rs1/rs2 are read addresses; rd is the write address. x0 stays zero and ignores writes. Reads do not wait for a clock; writes do.","x3'e 42 yaz, rs1=3,rs2=0 seç → r1=42,r2=0.","Write 42 to x3, select rs1=3,rs2=0 → r1=42,r2=0.","İki okuma çıkışını aynı MUX'a bağlamak rs1 ve rs2'yi bağımsız olmaktan çıkarır.","Sharing one selector between both reads destroys independent rs1/rs2 selection.","x0'a 99 yazmayı dene; sonra bütün okuma portlarından 0 kaldığını gör.","Try writing 99 to x0, then check it remains zero on both read ports."),
        "Decoder"=>g!("RISC-V çözücü komutun bitlerini alanlara böler. rd/rs1/rs2 sabit yerlerdedir; imm ise I,S,B,U,J biçimlerinde farklı toplanır. İşaret genişletme, bit31'in üst boşluğa kopyalanmasıdır.","RISC-V decoding splits instruction fields. rd/rs1/rs2 use fixed positions, while I/S/B/U/J immediates are assembled differently. Sign extension copies instruction bit31 into upper positions.","addi a0,a1,-1: rd=10,rs1=11,imm=0xFFFFFFFF.","addi a0,a1,-1: rd=10,rs1=11,imm=0xFFFFFFFF.","B/J ofsetlerinin en alt biti 0'dır; bit parçalarını kaydırmadan birleştirmek hedefi bozar.","B/J offsets have an implicit zero low bit; concatenating without it corrupts branch targets.","Pozitif ve negatif atlama kodunu assembler'da üretip çözücü çıktınla karşılaştır.","Assemble forward/backward branches and compare your decoder outputs."),
        "Control"=>g!("Kontrol, komutu yürütmek değil doğru parçaya izin vermektir. Opcode ailelerini ayır; ardından reg_we, mem_write, alu_b_imm ve wb_sel gibi sinyalleri çıkar. Her çıkışın yalnızca doğru komutlarda etkin olduğuna bak.","Control enables the right hardware rather than executing instructions itself. Decode opcode families, then derive reg_we,mem_write,alu_b_imm,wb_sel. Check that each output is asserted only for appropriate instructions.","sw → mem_write=1,reg_we=0; lw → mem_read=1,reg_we=1.","sw → mem_write=1,reg_we=0; lw → mem_read=1,reg_we=1.","Store'da reg_we'nin açık kalması komut bitlerinden sahte rd'ye yazabilir.","Leaving reg_we high on a store may write a spurious rd extracted from its bits.","Aynı funct3 ile load/store/op-imm ailelerini karşılaştır.","Compare load/store/op-immediate families sharing the same funct3."),
        "BranchUnit"=>g!("Karşılaştırıcı eq,lt,ltu üretir; dallanma birimi funct3'e göre bunlardan birini veya tersini seçer. Bu çip hedef adresi hesaplamaz, yalnızca al/alma kararı verir.","The comparator produces eq,lt,ltu; branch logic chooses one or its inverse using funct3. It does not calculate the target, only the taken/not-taken decision.","eq=1 için BEQ alınır, BNE alınmaz. Aynı koşulun iki yorumu.","With eq=1, BEQ is taken and BNE is not: opposite uses of one condition.","İşaretli BLT ile işaretsiz BLTU'nun seçim hattını tersleme.","Do not swap signed BLT and unsigned BLTU condition selection.","Aynı karşılaştırma bitleriyle BEQ/BNE, BLT/BGE çiftlerini dene.","Test BEQ/BNE and BLT/BGE pairs with identical comparison bits."),
        "LoadUnit"=>g!("Bellek hizalı 32-bit kelime verir. off istenen baytı/yarım kelimeyi seçer; birim onu alta kaydırıp gerektiği gibi işaret veya sıfır genişletir. Adres hesaplamak ALU'nun işidir.","Memory returns an aligned 32-bit word. off chooses a byte/halfword; this unit shifts it down and sign- or zero-extends. The ALU handles address calculation.","rdata=0x000080FF,off=0: lb=0xFFFFFFFF,lbu=255; off=1: lb=-128.","rdata=0x000080FF,off=0: lb=0xFFFFFFFF,lbu=255; off=1: lb=-128.","Bayt ofsetini bit kaydırma miktarı sanma: off=1 sekiz bit kaydırır.","A byte offset is not a bit shift: off=1 shifts eight bits.","Aynı kelimeyi dört bayt konumundan işaretli/işaretsiz oku.","Read all four byte positions with signed and unsigned loads."),
        "StoreUnit"=>g!("Kısmi yazma, veriyi kelimedeki doğru bayta taşımak ve yalnızca o baytları etkinleştirmektir. wmask her bayt için bir bit tutar. Bu çip RAM'i değil yazılacak veri ve izin maskesini üretir.","A subword store shifts data to the right byte positions and enables only those bytes. wmask has one bit per byte. This block produces write data/masks, not RAM itself.","sb data=0xAA,off=2 → wdata=0x00AA0000,wmask=0100.","sb data=0xAA,off=2 → wdata=0x00AA0000,wmask=0100.","Veriyi kaydırıp maskeyi kaydırmamak komşu baytları bozar.","Shifting data but not its mask corrupts neighbouring bytes.","sw,sh,sb için maskeleri ikilik yaz ve değişmeyen baytları işaretle.","Write binary masks for sw,sh,sb and mark preserved bytes."),
        "MulDiv"=>g!("Çarpma kaydırıp toplama, bölme ise kalanla çıkarma adımlarına ayrılır. İşaretli işlemlerde büyüklük ve işaret ayrı ele alınır. mul alt 32 biti, mulh türleri üst yarıyı seçer; bölüm ve kalan farklı sonuçlardır.","Multiplication breaks into shifted additions; division into remainder/subtraction steps. Signed operations handle magnitude and sign separately. mul selects low 32 bits; mulh variants select the high half; quotient and remainder differ.","7/3 → bölüm2,kalan1. RV32'de sıfıra bölmede bölüm tüm1, kalan bölünendir.","7/3 → quotient2,remainder1. RV32 division by zero gives all-ones quotient and the dividend as remainder.","İşaretli en küçük sayı / -1 taşması ve sıfıra bölme normal döngüden farklı kurallardır.","Signed minimum / -1 overflow and division by zero require explicit architectural rules.","Pozitif/negatif dört işaret birleşimini ve bölen0 durumunu dene.","Test all four sign combinations and a zero divisor."),
        "Cpu"=>g!("Bir komut çevriminde PC'den oku, çöz, register'ları oku, hesapla, bellek işlemini yap ve sonuç/PC'yi kenarda sakla. Hazır parçaların her birini doğru bağlamak kadar yan etki izinlerini bağlamak önemlidir. Komut çözümü ile ISA burada buluşur.","In one instruction cycle fetch at PC, decode, read registers, compute, access memory, then store result/PC at the edge. Wiring write permissions is as important as wiring data. This connects instruction decoding to the ISA.","add a0,a1,a2: a1/a2 → ALU → a0; PC+4. sw: ALU adresi → RAM, register yazılmaz.","add a0,a1,a2: a1/a2 → ALU → a0; PC+4. sw: ALU address → RAM, no register write.","jalr hedefinin alt bitini temizlemeyi ve dönüşte PC+4 yazmayı unutma.","Do not forget to clear jalr's low target bit or write PC+4 as the return address.","Önce üç komutluk programla başla; sonra dallanma, bellek ve fonksiyonu ayrı ayrı adımla.","Start with three instructions, then step branches, memory and calls separately."),
        "AddressDecode2"=>g!("Adres çözücü bir sayıyı tek-seçimli izinlere çevirir. en açıkken yalnızca bir hücre yazılabilir; kapalıyken hiçbiri yazılamaz.","An address decoder converts a number to one-hot enables. With en high exactly one cell may write; with en low none may write.","addr=2 (10),en=1 → s0=0,s1=0,s2=1,s3=0.","addr=2 (10),en=1 → s0=0,s1=0,s2=1,s3=0.","Düşük adres bitini üst bitle karıştırmak 1 ve 2 adreslerini değiştirir.","Swapping the low and high address bits exchanges addresses 1 and 2.","en=0 tutup dört adresi gez; bütün çıkışların 0 kaldığını doğrula.","Keep en=0 and visit all four addresses; verify every output stays zero."),
        "Rom4x8"=>g!("ROM sabit bir adres→veri tablosudur. Burada sabitler ve MUX ağacıyla kurulur; okuma için saat kenarı veya flip-flop gerekmez.","ROM is a fixed address-to-data table. Here constants and a MUX tree implement it; reading needs neither a clock edge nor flip-flops.","addr=1 → q=0xA5=165; addr=3 → q=0x80=128.","addr=1 → q=0xA5=165; addr=3 → q=0x80=128.","Sabitlerin genişliği 8 bit olmalı; 1-bit sabit 0xA5 baytını taşıyamaz.","Constants must be eight bits wide; a one-bit constant cannot carry byte 0xA5.","Dört adresi ters sırayla gez; okuma sırası içeriği değiştirmemeli.","Visit the four addresses in reverse order; read order must not alter contents."),
        "Ram4x8"=>g!("Dört adresin her biri bağımsız bir bayt tutar: toplam 32 bit. Adres çözücü yazma iznini, MUX ağacı okunacak baytı seçer.","Each of four addresses stores an independent byte: 32 bits total. The decoder chooses write enable; a MUX tree chooses the byte to read.","Adres 1'e 0xA5, adres 2'ye 0x3C yaz; yeniden 1'i oku → 0xA5.","Write 0xA5 at address 1 and 0x3C at address 2; read address 1 again → 0xA5.","we=0 okumayı kapatmaz. clk yüksek kalırken we'yi açmak yeni bir kenar değildir.","we=0 does not disable reading. Enabling we while clk remains high is not a new edge.","Bir hücreyi değiştirip diğer üçünü oku; hepsinin eski değerini koruduğunu dene.","Change one cell and read the other three; check they retain their earlier values."),
        "ProgramRom"=>g!("Kaynak kod assembler ile komut baytlarına dönüşür. ROM yalnızca bu baytları saklar; aynı veri bitlerini CPU komut olarak yorumlar.","An assembler turns source into instruction bytes. ROM only stores those bytes; the CPU interprets the same data bits as instructions.","ADD 0 → opcode 4, argüman 0 → 0100 0000 → 0x40.","ADD 0 → opcode 4, argument 0 → 0100 0000 → 0x40.","Mini ADD 0 sabit 0 eklemez; RAM[0]'daki değeri ekler. Bu yüzden sonuç 6 olur.","Mini ADD 0 adds RAM[0], not immediate zero. This is why the result becomes 6.","LDI 3'ü LDI 5 yaparsan hangi ROM baytı ve RAM sonuçları değişir? Dünya'da dene.","If LDI 3 becomes LDI 5, which ROM byte and RAM results change? Try it in World."),
        "RomSequencer"=>g!("Komut getirme, yürütmeden ayrıdır: PC adresi tutar, ROM baytı gösterir. HLT adresi durdurur; reset ve yükleme durmadan önceliklidir.","Fetching is distinct from execution: PC holds an address, ROM shows its byte. HLT stops advancement; reset and load override the stop.","pc=3 → instr=0x31; run ile kenar → pc=4,instr=0xF0; sonraki kenarda pc=4 kalır.","pc=3 → instr=0x31; a run edge → pc=4,instr=0xF0; the next edge keeps pc=4.","Komutları sırayla görmek ADD'in yürütüldüğü anlamına gelmez; burada akümülatör ve veri RAM'i yoktur.","Seeing instructions in sequence does not execute ADD; this circuit has no accumulator or data RAM.","load ile 15'e git, bir adımda 0'a sarmayı dene. Sonra HLT'de run=0 iken reset ver.","Load address 15 and step once to test wrapping to 0. Then reset at HLT with run=0."),
        "Simd4"=>g!("SIMD, tek bir komutla birçok veri üzerinde aynı işlemi yapmaktır. Geniş bir yazmaç şeritlere bölünür; şeritler arasında elde geçmez. Doyurmalı toplama, renk taşınca siyaha dönmek yerine beyazda kalmasını sağlar.","SIMD means doing the same operation on many data with one instruction. A wide register is split into lanes; no carry crosses between lanes. Saturating addition makes an overflowing colour stay white instead of wrapping to black.","a=0x01FF_C864, b=0x0101_6464: sat=0 → 0x0200_2CC8; sat=1 → 0x02FF_FFC8.","a=0x01FF_C864, b=0x0101_6464: sat=0 → 0x0200_2CC8; sat=1 → 0x02FF_FFC8.","Tek bir Adder32 kullanmak bir şeridin eldesini yandakine taşır: 0xFF + 1 yandaki baytı bozar.","Using one Adder32 carries a lane's overflow into the next: 0xFF + 1 corrupts the neighbouring byte.","Bir resmin parlaklığını artırmak için her piksele 40 ekle: sat=0 ve sat=1 arasındaki farkı düşün.","Add 40 to every pixel to brighten an image: think about the difference between sat=0 and sat=1."),
        "Edge"=>g!("Kenar fonksiyonu, iki vektörün çapraz çarpımıdır. İşareti noktanın kenarın hangi yanında olduğunu, büyüklüğü kenara uzaklığıyla orantılı bir değeri verir. GPU'lar bu değerleri renkleri ve dokuları köşeler arasında karıştırmak için de kullanır.","The edge function is the cross product of two vectors. Its sign says which side of the edge the point is on; its size is proportional to the distance from the edge. GPUs also use these values to blend colours and textures between corners.","a=(0,0), b=(10,0): p=(5,3) → E = 10×3 − 0×5 = 30 → right=1. p kenarın üstündeyse, örneğin (5,0): E=0, right=1.","a=(0,0), b=(10,0): p=(5,3) → E = 10×3 − 0×5 = 30 → right=1. On the edge, say (5,0): E=0, right=1.","Koordinat farklarını işaretsiz düşünmek, nokta kenarın solundayken de pozitif sonuç verir.","Treating coordinate differences as unsigned gives a positive result even when the point is on the left.","a ile b'yi yer değiştir: her noktanın cevabı tersine mi döner? Kenarın üstündeki noktalar ne olur?","Swap a and b: does every point's answer flip? What happens to points on the edge?"),
        "Triangle"=>g!("Bir nokta, bir üçgenin üç kenarının da aynı yanındaysa içindedir. Her piksel bağımsız test edildiği için binlerce piksel aynı anda hesaplanabilir. GPU'ların bu kadar paralel olmasının nedeni budur.","A point is inside a triangle if it is on the same side of all three edges. Each pixel is tested independently, so thousands can be computed at once. That is why GPUs are so parallel.","a=(0,0), b=(10,0), c=(0,10): (1,1) içeride, (6,6) dışarıda (b→c kenarının solunda).","a=(0,0), b=(10,0), c=(0,10): (1,1) is inside, (6,6) is outside (left of edge b→c).","Köşeleri ters sırada (saat yönünün tersine) verirsen içerisi hiçbir kenarın sağında olmaz: üçgen boş çıkar.","If the corners come in the other order (counter-clockwise), the inside is on the right of no edge: the triangle comes out empty.","Gerçek GPU'lar ters sıralı üçgenleri 'arka yüz' sayıp çizmez. Bu neden işe yarar?","Real GPUs skip counter-clockwise triangles as 'back faces'. Why is that useful?"),
        "ScanCounter"=>g!("Bir ekran, pikselleri sabit bir sırayla tarar. Bu sayaç her piksele bir kez uğrar; her uğrayışta o pikselin rengi hesaplanabilir. Eski CRT ekranlarda elektron demeti tam olarak böyle hareket ederdi.","A screen scans its pixels in a fixed order. This counter visits each pixel once; at each visit that pixel's colour can be computed. On old CRT screens the electron beam moved exactly like this.","(31, 4) → bir kenar → (0, 5). (31, 31) → (0, 0).","(31, 4) → one edge → (0, 5). (31, 31) → (0, 0).","y'yi her saatte artırmak ekranı çapraz tarar; y yalnızca x taştığında artmalı.","Increasing y every clock scans the screen diagonally; y must only go up when x overflows.","Bir kare 1024 saat sürüyor. Saniyede 60 kare için saat kaç Hz olmalı?","A frame takes 1024 clocks. How fast must the clock be for 60 frames a second?"),
        "Fill"=>g!("Rasterleyici, bir şekli piksellere çevirir. Burada pikseller sırayla, tek tek hesaplanıyor. Gerçek GPU'lar ekranı karolara böler ve her karonun piksellerini yüzlerce çekirdekle aynı anda hesaplar.","A rasterizer turns a shape into pixels. Here pixels are computed one by one, in order. Real GPUs split the screen into tiles and compute each tile's pixels with hundreds of cores at once.","Köşeler (2,3), (29,8), (9,27): bir karede 309 piksel yanar.","Corners (2,3), (29,8), (9,27): 309 pixels light up in a frame.","x ve y'yi Triangle'a vermeden önce bir saat geciktirmek, üçgeni bir piksel kaydırır.","Delaying x and y by a clock before the Triangle shifts the triangle by a pixel.","Dünya'da iki Fill koy, aynı ekrana iki üçgen çizdir. OR ile birleştirmek ne demek?","Put two Fills in World and draw two triangles on one screen. What does combining them with OR mean?"),
        "FastAdd32"=>g!("Bir devrenin hızı, en uzun yolundaki kapı sayısıyla ölçülür: saat ancak bu yol durulduktan sonra vurabilir. Elde seçmeli toplayıcı fazladan kapı harcayarak eldeyi beklemeyi kısaltır. Gerçek işlemcilerde aynı amaçla elde öngörülü (carry-lookahead) toplayıcılar kullanılır.","A circuit's speed is measured by the gates on its longest path: the clock can only tick once that path settles. A carry-select adder spends extra gates to wait less for the carry. Real processors use carry-lookahead adders for the same reason.","0xFF + 0x01: alt bayt eldeyi 1 yapar; üst bayt için elde-1 toplamı zaten hazırdır, MUX onu seçer.","0xFF + 0x01: the low byte makes the carry 1; the carry-1 sum for the next byte is already there, and the MUX picks it.","İki toplamı da hesaplayıp yanlış eldeyle seçmek sadece bazı girişlerde hata verir: 0xFF..FF + 1'i dene.","Computing both sums but selecting with the wrong carry fails only on some inputs: try 0xFF..FF + 1.","Bayt yerine 4 bitlik gruplarla kur: yol daha mı kısa, kapı daha mı çok?","Build it with 4-bit groups instead of bytes: is the path shorter, are there more gates?"),
        "PipeAdd32"=>g!("Boru hattı bir işi aşamalara böler ve araya yazmaç koyar. Her aşama kısa olduğu için saat hızlanır. Gecikme (bir sonucun çıkması için geçen saat) artar ama verim (saat başına sonuç) aynı kalır. İşlemcilerde aşamalar getir, çöz, yürüt, bellek ve geri yazmadır.","A pipeline splits work into stages with registers between them. Each stage is short, so the clock speeds up. Latency (clocks until one result comes out) grows, but throughput (results per clock) stays the same. In processors the stages are fetch, decode, execute, memory and write-back.","Kenar 1: 0xFFFF + 1 girer, alt yarı 0 ve elde 1 yazmaca. Kenar 1'den sonra sum = 0x10000.","Edge 1: 0xFFFF + 1 enters; the low half 0 and carry 1 go into the register. After edge 1, sum = 0x10000.","Alt eldesini yazmaca koymayı unutmak, üst yarıyı ancak elde gerekmediğinde doğru verir.","Forgetting to register the low carry gives a right upper half only when no carry is needed.","Üç aşamalı yap: yol ne kadar kısalır, gecikme kaç saat olur?","Make it three stages: how much shorter is the path, how many clocks is the latency?"),
        "Forward"=>g!("Boru hattında bir komut, öncekinin sonucu register dosyasına yazılmadan onu okumak isteyebilir: buna veri tehlikesi (hazard) denir. Beklemek yerine sonucu doğrudan ALU'nun girişine yönlendirmek boru hattını dolu tutar. Yeni sonuç her zaman eskisinden önceliklidir.","In a pipeline an instruction may read a result before it reaches the register file: a data hazard. Forwarding the result straight to the ALU's input instead of waiting keeps the pipeline full. The newest result always takes priority.","add x5,x1,x2 sonra sub x6,x5,x3: ikinci komutta rs1=5, ex_rd=5 → fa=1.","add x5,x1,x2 then sub x6,x5,x3: for the second, rs1=5, ex_rd=5 → fa=1.","x0'a yazan bir komutu yönlendirmek, x0'ı okuyan komuta çöp değer verir.","Forwarding from an instruction that writes x0 gives garbage to an instruction reading x0.","Bir yükleme komutunun sonucu EX'te henüz yoktur. Bu durumda ne yapmak gerekir?","A load's result is not yet available in EX. What has to happen then?"),
        "Cache4"=>g!("Önbellek, son kullanılan verilerin hızlı bir kopyasıdır. Doğrudan eşlemede her adres tek bir satıra düşer; etiket, satırdaki verinin hangi adrese ait olduğunu söyler. Geçerli biti, açılışta rastgele bir etiketin yanlışlıkla eşleşmesini önler.","A cache is a fast copy of recently used data. In direct mapping each address falls into one line; the tag says which address the line's data belongs to. The valid bit stops a random tag at power-on from matching by accident.","0x05 ve 0x09 aynı satıra (1) düşer: biri yazılınca diğeri ıskalar. Buna çakışma denir.","0x05 and 0x09 fall into the same line (1): writing one makes the other miss. That is a conflict.","Etiketi karşılaştırmadan hit vermek, aynı satıra düşen başka bir adresin verisini döndürür.","Signalling hit without comparing the tag returns the data of another address in the same line.","Bir programın sırayla 0'dan 15'e kadar okuduğunu düşün: kaç ıskalama olur?","Imagine a program reading addresses 0 to 15 in order: how many misses happen?"),
        "SeqMulDiv"=>g!("Uzun bir kombinasyonel yolu saatlere bölmek, aynı donanımı tekrar tekrar kullanmaktır: bir toplayıcı, 32 kenar boyunca 32 toplayıcının işini görür. Devre küçülür, yolu kısalır, ama sonuç birkaç saat sonra gelir. ready, işi kullanan devreye ne zaman bakacağını söyler.","Splitting a long combinational path across clocks reuses the same hardware: one adder does the work of 32 over 32 edges. The circuit shrinks and its path shortens, but the result comes several clocks later. ready tells the circuit using it when to look.","7 × 3: Q=3, M=7. Adım 1: Q[0]=1 → A=7, kaydır. Adım 2: Q[0]=1 → A'ya yine 7 eklenir… 32 adımdan sonra {A,Q}=21.","7 × 3: Q=3, M=7. Step 1: Q[0]=1 → A=7, shift. Step 2: Q[0]=1 → 7 is added to A again… after 32 steps {A,Q}=21.","go düşünce yarım kalan iş temizlenmezse sonraki işlem eski kalanla başlar.","If a half-finished operation is not cleared when go drops, the next one starts with a stale remainder.","Kaç kenar sürdüğünü say: işaretli ve işaretsiz bölme aynı sayıda mı?","Count the edges: do signed and unsigned division take the same number?"),
        "CpuSeq"=>g!("Çok saatli bir birim, işlemciyi beklemeye (stall) zorlar: pc ve register yazımı ready gelene kadar tutulur. Saat, artık en yavaş komuta değil tek bir adıma göre ayarlanır. Gerçek işlemcilerde bölme on saatlerce sürer, toplama ise bir saat.","A multi-clock unit makes the processor stall: the pc and register write are held until ready comes. The clock is now set by one step, not by the slowest instruction. In real processors a divide takes tens of clocks, an add one.","div a0, a1, a2: pc 35 saat boyunca aynı kalır, a0 yalnızca son saatte yazılır. Sonraki addi tek saatte biter.","div a0, a1, a2: the pc stays put for 35 clocks and a0 is written only at the last one. The next addi takes one clock.","Bekleme sırasında register yazmayı kapatmazsan rd her saatte yarım sonuçla yazılır; rd = rs1 ise sonuç bozulur.","If register write is not held while waiting, rd is written with half results every clock; with rd = rs1 the result goes wrong.","Bilgisayarda bir program çalıştır ve komut sayısını saat sayısıyla karşılaştır.","Run a program on the computer and compare the instruction count with the clock count."),
        "Shade"=>g!("Renk üç sayıdır: kırmızı, yeşil ve mavi. Her kanal aynı formülle ayrı hesaplanır; aralarında elde geçmez. Uzaklık sisi (fog) en basit gölgelendirmedir: uzak pikseller koyulaşır, sahne derinlik kazanır.","A colour is three numbers: red, green and blue. Each channel is computed separately by the same formula; no carry passes between them. Distance fog is the simplest shading: far pixels darken and the scene gains depth.","color=0xFE3, near=250 (k=3) → 0xFE3 kalır. near=60 (k=0) → her kanal ÷ 4: 0x330.","color=0xFE3, near=250 (k=3) → stays 0xFE3. near=60 (k=0) → each channel ÷ 4: 0x330.","Kanalları tek bir 12 bitlik sayı gibi çarparsan bir kanalın taşması yandakine geçer.","Multiplying the channels as one 12-bit number lets one channel's overflow leak into the next.","Aynı rengi dört k değeriyle dene: parlaklık dört basamakta artmalı.","Try the same colour with all four k values: brightness should rise in four steps."),
        "DepthTest"=>g!("Derinlik tamponu her piksel için tek bir sayı saklar: şimdiye kadarki en yakın şeyin yakınlığı. Üçgenlerin çizim sırası önemsizleşir; yakın olan her zaman kazanır.","A depth buffer stores one number per pixel: the nearness of the closest thing so far. The order triangles are drawn in stops mattering; the nearer one always wins.","Arka üçgen önce: near=60 > old=0 → yazılır, old=60 olur. Sonra ön üçgen: 160 > 60 → yazılır. Ters sırada arka üçgen 60 > 160 değil → yazılmaz.","Back triangle first: near=60 > old=0 → written, old becomes 60. Then the front one: 160 > 60 → written. The other way round, the back one: 60 > 160 is false → not written.","near ≥ old kullanırsan eşit yakınlıktaki iki üçgen sırayla birbirini ezer; burada eşitlik yazmaz.","With near ≥ old, two triangles at the same nearness overwrite each other in turn; here equal does not write.","on=0 iken near'ı 255 yap: write yine 0 kalmalı.","Set near to 255 with on=0: write must still be 0."),
        "FrameScan"=>g!("Sayaçlar basamak basamak taşar: saniyeler dakikaya, dakikalar saate. Burada pikseller satıra, satırlar kareye, kareler üçgen sırasına taşar.","Counters carry digit by digit: seconds into minutes, minutes into hours. Here pixels carry into rows, rows into frames, frames into the triangle number.","x=31,y=31,t=1 → kenarda x=0,y=0,t=2. x=31,y=5 → x=0,y=6, t aynı.","x=31,y=31,t=1 → at the edge x=0,y=0,t=2. x=31,y=5 → x=0,y=6, t unchanged.","t'yi x her taştığında artırırsan her satırda üçgen değişir.","Increasing t whenever x wraps changes the triangle on every row.","Bir kare 1024 saat: 4096 saat sonra t yeniden 0 mı?","A frame is 1024 clocks: after 4096 clocks is t back to 0?"),
        "Raster3"=>g!("Bir GPU'nun ilk aşamaları: tara, kapsamayı test et, derinliği karşılaştır, gölgele. Her biri bağımsız bir birimdir; bu yüzden GPU'lar onları boru hattına dizer ve binlerce pikseli aynı anda işler.","The first stages of a GPU: scan, test coverage, compare depth, shade. Each is an independent unit, which is why GPUs line them up in a pipeline and process thousands of pixels at once.","Sarı üçgen (near=250) diğerlerinin önündedir: hangi karede çizilirse çizilsin üstte kalır.","The yellow triangle (near=250) is in front of the others: whichever frame draws it, it stays on top.","old'u bu pikselin değil başka bir pikselin tampon değeriyle karşılaştırmak, üçgenleri yanlış yerden keser.","Comparing with another pixel's buffer value cuts the triangles in the wrong places.","Dünya'da sahneyi çalıştır, sonra ROM'da bir üçgenin near değerini değiştir.","Run the scene in World, then change one triangle's near in the ROM."),
        _=>return None,
    })
}

#[cfg(test)]
mod tests {
    #[test]
    fn every_level_has_a_complete_guide_in_both_languages() {
        for lang in makine_lang::Lang::ALL {
            makine_lang::set_for_thread(Some(lang));
            for level in crate::levels() {
                let g = super::guide(level.chip).unwrap_or_else(|| panic!("{}", level.chip));
                for text in [g.concept, g.example, g.trap, g.experiment] {
                    assert!(text.len() > 20, "{}", level.chip);
                }
            }
        }
        makine_lang::set_for_thread(None);
    }
}
